(function () {
  'use strict';
  const DB_KEY='itAssetDemoDB.v3', SESSION_KEY='itAssetDemoSession', PAGE_SIZE=8;
  const app=document.getElementById('app'); let db; let user; let demoNoticeShown=false; let aiSelection=null;
  const AI_CATALOG={
    dell5440:{marca:'Dell',modelo:'Latitude 5440',service_tag:'DL5440-DEMO',serial:'8GH2DEMO',components:{processor:'Intel Core i7-1365U',generation:'13ª',ram:'16 GB',ram_slots:'2',ram_type:'DDR5',primary_disk:'512 GB NVMe',storage_capacity:'512 GB',storage_type:'NVMe',graphics:'Intel Iris Xe',display:'14 pulgadas',resolution:'1920×1080',battery:'54 Wh',windows:'Windows 11 Pro',office:'Microsoft 365',antivirus:'Microsoft Defender'}},
    hp840:{marca:'HP',modelo:'EliteBook 840 G8',service_tag:'HP840-DEMO',serial:'5CG1DEMO',components:{processor:'Intel Core i5-1145G7',generation:'11ª',ram:'16 GB',ram_slots:'2',ram_type:'DDR4',primary_disk:'512 GB NVMe',storage_capacity:'512 GB',storage_type:'NVMe',graphics:'Intel Iris Xe',display:'14 pulgadas',resolution:'1920×1080',battery:'53 Wh',windows:'Windows 11 Pro',office:'Microsoft 365',antivirus:'Microsoft Defender'}},
    lenovoT14:{marca:'Lenovo',modelo:'ThinkPad T14 Gen 3',service_tag:'LNT14-DEMO',serial:'PF3XDEMO',components:{processor:'AMD Ryzen 7 PRO 6850U',generation:'Ryzen 6000',ram:'16 GB',ram_slots:'2',ram_type:'DDR5',primary_disk:'1 TB NVMe',storage_capacity:'1 TB',storage_type:'NVMe',graphics:'AMD Radeon 680M',display:'14 pulgadas',resolution:'1920×1200',battery:'52.5 Wh',windows:'Windows 11 Pro',office:'Microsoft 365',antivirus:'Microsoft Defender'}},
    macbookM2:{marca:'Apple',modelo:'MacBook Air M2',service_tag:'MBA-M2-DEMO',serial:'C02M2DEMO',components:{processor:'Apple M2',generation:'M2',ram:'16 GB',primary_disk:'512 GB SSD',storage_capacity:'512 GB',storage_type:'SSD',graphics:'GPU Apple de 10 núcleos',display:'13.6 pulgadas',resolution:'2560×1664',battery:'52.6 Wh',windows:'macOS Sonoma',antivirus:'Protección nativa macOS'}}
  };
  const COMPONENT_LABELS={processor:'Procesador',generation:'Generación',ram:'Memoria RAM',ram_slots:'Ranuras RAM',ram_type:'Tipo de memoria',primary_disk:'Disco principal',secondary_disk:'Disco secundario',storage_capacity:'Capacidad',storage_type:'Tipo de almacenamiento',graphics:'Tarjeta gráfica',display:'Pantalla',resolution:'Resolución',battery:'Batería',battery_cycles:'Ciclos de batería',battery_health:'Salud de batería',mac_address:'Dirección MAC',ip_address:'Dirección IP',bios:'Versión BIOS',tpm:'Módulo TPM',windows:'Sistema operativo',office:'Suite de oficina',antivirus:'Antivirus',notes:'Notas'};
  const clone=value=>JSON.parse(JSON.stringify(value));
  const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const today=()=>new Date().toISOString().slice(0,10);
  const byId=(items,id)=>items.find(item=>item.id===Number(id));
  const nextId=items=>Math.max(0,...items.map(item=>item.id))+1;
  const value=(form,name)=>form.elements[name]?.value?.trim()||'';
  const delay=()=>new Promise(resolve=>setTimeout(resolve,500+Math.floor(Math.random()*701)));
  function load(){ try{db=JSON.parse(localStorage.getItem(DB_KEY));}catch{db=null;} if(!db||db.version!==window.DEMO_SEED.version){db=clone(window.DEMO_SEED);save();} try{user=byId(db.users,JSON.parse(localStorage.getItem(SESSION_KEY))?.userId);}catch{user=null;} }
  function save(){localStorage.setItem(DB_KEY,JSON.stringify(db));}
  function audit(action,detail=''){db.audit.unshift({id:nextId(db.audit),date:new Date().toISOString(),user:user?.username||'Sistema',action,detail});save();}
  function toast(message,type='success'){let stack=document.querySelector('.toast-stack');if(!stack){stack=document.createElement('div');stack.className='toast-stack';document.body.append(stack);}const item=document.createElement('div');item.className=`toast ${type}`;item.innerHTML=`<strong>${type==='success'?'✓':'!'}</strong> ${esc(message)}`;stack.append(item);setTimeout(()=>item.remove(),3300);}
  function loader(label='Procesando…'){let el=document.getElementById('page-loader');if(!el){el=document.createElement('div');el.id='page-loader';el.className='page-loader';el.innerHTML='<span class="page-loader-spinner"></span><span class="page-loader-label"></span>';document.body.append(el);}el.querySelector('.page-loader-label').textContent=label;el.classList.add('active');}
  function stopLoader(){document.getElementById('page-loader')?.classList.remove('active');}
  function demoSignature(name,type){const initials=String(name||'Demo').split(/\s+/).map(x=>x[0]).join('').slice(0,2);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="520" height="170" viewBox="0 0 520 170"><rect width="520" height="170" fill="#fff"/><path d="M65 112 C105 38 114 145 158 79 S211 133 260 72 S326 125 386 75" fill="none" stroke="#172033" stroke-width="4" stroke-linecap="round"/><text x="400" y="108" font-family="cursive" font-size="28" fill="#172033">${esc(initials)}</text><text x="260" y="151" text-anchor="middle" font-family="Arial" font-size="12" fill="#667085">FIRMA ${esc(type).toUpperCase()} · DATOS DEMO</text></svg>`;return `data:image/svg+xml,${encodeURIComponent(svg)}`;}
  function showDemoNotice(){
    if(demoNoticeShown)return;
    demoNoticeShown=true;
    const notice=document.createElement('div');
    notice.className='modal active demo-notice';
    notice.setAttribute('role','dialog');
    notice.setAttribute('aria-modal','true');
    notice.setAttribute('aria-labelledby','demo-notice-title');
    notice.innerHTML=`<div class="modal-content"><div class="modal-header"><div><p class="eyebrow">VERSIÓN DE PORTAFOLIO</p><h2 id="demo-notice-title">Esta es una demostración</h2></div></div><div class="demo-notice-body"><p>Estás viendo una versión demostrativa preparada para funcionar completamente desde GitHub Pages.</p><p>La aplicación original cuenta con todas las funciones en producción, incluyendo backend, base de datos, integraciones, procesos automáticos y automatizaciones empresariales.</p><p>En esta demo los datos y las respuestas del sistema se simulan localmente para que puedas explorar la experiencia de usuario sin conectarte a un servidor.</p></div><div class="modal-actions"><button class="btn primary" type="button" data-demo-dismiss>Entendido, ver demo</button></div></div>`;
    document.body.append(notice);
    document.body.classList.add('modal-open');
    notice.querySelector('[data-demo-dismiss]').onclick=()=>{notice.remove();document.body.classList.remove('modal-open');};
  }
  async function perform(label,fn){loader(label);await delay();try{fn();save();render();toast('Cambios guardados correctamente');}catch(error){console.error(error);toast(error.message||'No se pudo completar la acción','error');}finally{stopLoader();}}
  function navigate(route){location.hash=route.startsWith('#')?route:`#/${route.replace(/^\//,'')}`;}
  function route(){return (location.hash.replace(/^#\/?/,'')||'dashboard').split('/');}
  function modal(id,content){return `<div class="modal" id="${id}"><div class="modal-content">${content}</div></div>`;}
  function modalHead(title,copy=''){return `<div class="modal-header"><div><h2>${esc(title)}</h2>${copy?`<p>${esc(copy)}</p>`:''}</div><button class="close" type="button" data-close>×</button></div>`;}
  function options(items,selected,label=x=>x.nombre){return items.map(x=>`<option value="${x.id}" ${Number(selected)===x.id?'selected':''}>${esc(label(x))}</option>`).join('');}
  function empty(cols,text){return `<tr><td colspan="${cols}" class="empty">${esc(text)}</td></tr>`;}
  function shell(title,content){
    const admin=user.role==='admin'; const link=(path,icon,name,sub)=>`<a href="#/${path}" data-route="${path}"><span class="nav-icon">${icon}</span><span class="nav-text"><strong>${name}</strong><small>${sub}</small></span></a>`;
    return `<aside class="sidebar" id="sidebar"><div class="sidebar-aura"></div><div class="sidebar-head"><a class="brand" href="#/dashboard"><span class="brand-mark"><i></i><i></i></span><span class="brand-copy"><strong>IT Asset</strong><small>Manager</small></span><span class="brand-version">V3</span></a><button class="sidebar-close" type="button" data-sidebar-close>×</button></div><div class="sidebar-navigation"><div class="nav-section"><p class="nav-label">Principal</p><nav class="menu">${link('dashboard','⌂','Resumen','Vista general')}${link('loans','⇄','Préstamos','Entregas y devoluciones')}</nav></div>${admin?`<div class="nav-section"><p class="nav-label">Operaciones</p><nav class="menu">${link('laptops','▱','Equipos','Inventario tecnológico')}${link('employees','♙','Personas','Usuarios de activos')}${link('accessories','⌘','Accesorios','Periféricos y extras')}${link('incidents','!','Incidencias','Soporte y seguimiento')}${link('maintenance','◇','Mantenimiento','Servicio técnico')}</nav></div><div class="nav-section"><p class="nav-label">Administración</p><nav class="menu">${link('users','♢','Usuarios','Accesos y roles')}${link('audit','≡','Auditoría','Registro de actividad')}</nav></div>`:''}<div class="nav-section nav-section-last"><nav class="menu">${link('about','i','Acerca del sistema','Información y versión')}</nav></div></div><div class="sidebar-foot"><span class="user-avatar">${esc(user.username[0].toUpperCase())}</span><span class="user-copy"><strong>${esc(user.username)}</strong><small><i></i>${admin?'Administrador':'Visitante'}</small></span><button class="logout" type="button" data-logout title="Cerrar sesión">↪</button></div></aside><button class="sidebar-backdrop" data-sidebar-close></button><main class="main"><header class="topbar"><button class="menu-toggle" aria-label="Abrir menú">☰</button><div><p class="eyebrow">${admin?'PANEL DE ADMINISTRACIÓN':'MI PORTAL'}</p><h1>${esc(title)}</h1></div><button class="theme-toggle" title="Cambiar tema">◐</button></header>${content}</main>`;
  }
  function login(){document.body.className='login-page';app.innerHTML=`<main class="login-shell"><section class="login-showcase" aria-hidden="true"><div class="login-orb orb-one"></div><div class="login-orb orb-two"></div><div class="login-brand"><span class="login-mark">◆</span><span>IT ASSET MANAGER</span></div><div class="login-copy"><p class="login-kicker">GESTIÓN TECNOLÓGICA</p><h1>Tu inventario,<br>siempre bajo control.</h1><p>Administra equipos, préstamos, mantenimiento e incidencias desde un solo lugar.</p></div><div class="login-benefits"><span>Inventario centralizado</span><span>Control de préstamos</span><span>Historial auditable</span></div></section><section class="login-card"><div class="login-card-header"><div class="login-mark mobile-mark">◆</div><p class="login-kicker">BIENVENIDO</p><h2>Inicia sesión</h2><p>Accede a tu panel de gestión IT.</p></div><div id="login-error"></div><form data-action="login"><div class="form-group"><label for="email">Correo</label><div class="login-input"><span>◉</span><input id="email" name="email" type="email" placeholder="admin@demo.com" required autofocus></div></div><div class="form-group"><label for="password">Contraseña</label><div class="login-input"><span>⌁</span><input id="password" name="password" type="password" placeholder="Tu contraseña" required></div></div><button class="btn btn-primary login-button"><span>Entrar al sistema</span><span>→</span></button></form><div class="demo-credentials"><p><strong>Administrador:</strong> admin@demo.com / admin123</p><p><strong>Usuario:</strong> user@demo.com / user123</p></div></section></main>`;bind();}
  function dashboard(){const count=s=>db.laptops.filter(x=>x.estado===s).length, active=db.loans.filter(x=>x.estado==='Activo'), overdue=active.filter(x=>x.fecha_devolucion&&x.fecha_devolucion<today());const groups=key=>Object.entries(db.laptops.reduce((a,x)=>(a[x[key]]=(a[x[key]]||0)+1,a),{}));const chart=rows=>`<div class="native-chart">${rows.map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><i style="width:${Math.min(v*18,100)}%"></i><b>${v}</b></div>`).join('')}</div>`;return shell('Resumen',`<section class="metrics"><article><span>Laptops disponibles</span><strong>${count('Disponible')}</strong><a href="#/laptops">Ver equipos</a></article><article><span>Prestadas</span><strong>${count('Prestado')}</strong><a href="#/loans">Ver préstamos</a></article><article><span>Mantenimiento</span><strong>${count('Mantenimiento')}</strong><a href="#/maintenance">Gestionar</a></article><article><span>Préstamos activos</span><strong>${active.length}</strong><a href="#/loans">Gestionar</a></article></section>${overdue.length?`<section class="notice warning"><div><strong>Hay ${overdue.length} préstamo(s) vencido(s)</strong><p>Revisa las fechas de devolución programadas.</p></div><a href="#/loans">Ver alertas</a></section>`:''}<section class="chart-grid"><article class="panel"><h2>Activos por estado</h2>${chart(groups('estado'))}</article><article class="panel"><h2>Activos por marca</h2>${chart(groups('marca'))}</article></section><section class="panel"><div class="panel-title"><div><h2>Actividad reciente</h2><p>Últimos movimientos de equipos</p></div><a class="btn secondary" href="#/loans">Ver todos</a></div><div class="table-scroll"><table><thead><tr><th>Persona</th><th>Equipo</th><th>Entrega</th><th>Estado</th></tr></thead><tbody>${db.loans.slice().sort((a,b)=>b.id-a.id).slice(0,5).map(x=>`<tr><td>${esc(byId(db.employees,x.employee_id)?.nombre)}</td><td>${esc(byId(db.laptops,x.laptop_id)?.service_tag)}</td><td>${x.fecha_entrega}</td><td><span class="badge ${x.estado==='Activo'?'amber':'green'}">${x.estado}</span></td></tr>`).join('')}</tbody></table></div></section>`);}
  const laptopForm=(x={})=>`<div class="form-grid"><label>Service Tag<input name="service_tag" value="${esc(x.service_tag)}" required pattern="[A-Za-z0-9-]{4,30}"></label><label>Marca<input name="marca" value="${esc(x.marca)}" required></label><label>Modelo<input name="modelo" value="${esc(x.modelo)}" required></label><label>Número de serie<input name="serial" value="${esc(x.serial)}" required></label><label>Estado<select name="estado">${['Disponible','Prestado','Mantenimiento','Dañado'].map(v=>`<option ${x.estado===v?'selected':''}>${v}</option>`)}</select></label><label>Observaciones<textarea name="observaciones">${esc(x.observaciones)}</textarea></label></div>`;
  function laptops(){const rows=db.laptops.map(x=>`<tr><td><a class="link" href="#/laptops/${x.id}">${esc(x.service_tag)}</a></td><td>${esc(x.marca)}</td><td>${esc(x.modelo)}</td><td>${esc(x.serial)}</td><td><span class="badge">${esc(x.estado)}</span></td><td class="row-actions"><button class="icon-btn" data-edit-laptop="${x.id}">✎</button><a class="icon-btn" href="#/laptops/${x.id}">↗</a><button class="icon-btn" data-qr="${x.id}">▦</button><button class="icon-btn danger" data-delete="laptops:${x.id}:${esc(x.service_tag)}">×</button></td></tr>`).join('');return shell('Equipos',`<section class="toolbar"><input class="search" data-table-search="laptops-table" placeholder="Buscar por Service Tag, marca o serial"><select data-table-filter="laptops-table" data-column="4"><option value="">Todos los estados</option>${['Disponible','Prestado','Mantenimiento','Dañado'].map(v=>`<option>${v}</option>`)}</select><div class="toolbar-actions"><button class="btn secondary" data-open="aiLaptop">Añadir con IA · Demo</button><button class="btn primary" data-open="newLaptop">+ Nuevo equipo</button></div></section><section class="panel"><div class="table-scroll"><table id="laptops-table"><thead><tr><th data-sort>Service Tag ↕</th><th data-sort>Marca ↕</th><th>Modelo</th><th>Serial</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows||empty(6,'No hay equipos registrados.')}</tbody></table></div><div class="pagination" data-pagination="laptops-table"></div></section>${modal('aiLaptop',modalHead('Añadir equipo con IA · Demo','Asistente simulado con modelos y especificaciones predefinidas.')+`<div class="ai-demo-notice"><strong>Simulación local</strong><span>Esta función no consulta una IA real ni envía información a internet. Utiliza un catálogo local preparado exclusivamente para demostrar la automatización de la aplicación original.</span></div><div class="ai-search"><label>Modelo de demostración<select id="aiDemoModel"><option value="dell5440">Dell Latitude 5440</option><option value="hp840">HP EliteBook 840 G8</option><option value="lenovoT14">Lenovo ThinkPad T14 Gen 3</option><option value="macbookM2">Apple MacBook Air M2</option></select></label><button class="btn primary" type="button" data-ai-search>Generar propuesta</button></div><div id="aiDemoLoading" class="ai-loading" hidden>Analizando datos predefinidos…</div><div id="aiDemoPreview" class="ai-preview" hidden></div><div class="modal-actions"><button class="btn secondary" type="button" data-close>Cancelar</button><button id="aiDemoApply" class="btn primary" type="button" data-ai-apply hidden>Aplicar al formulario</button></div>`)}${modal('newLaptop',modalHead('Registrar equipo','Completa la información de inventario.')+`<form data-action="create-laptop">${laptopForm()}<div class="modal-actions"><button class="btn secondary" type="button" data-close>Cancelar</button><button class="btn primary">Guardar equipo</button></div></form>`)}${db.laptops.map(x=>modal(`editLaptop${x.id}`,modalHead(`Editar ${x.service_tag}`)+`<form data-action="edit-laptop" data-id="${x.id}">${laptopForm(x)}<div class="modal-actions"><button class="btn primary">Guardar cambios</button></div></form>`)).join('')}`);}
  function laptopDetail(id){const x=byId(db.laptops,id);if(!x)return notFound();const loans=db.loans.filter(l=>l.laptop_id===x.id),c=x.components||{};const fields=Object.keys(COMPONENT_LABELS);return shell('Detalle de equipo',`<a class="back" href="#/laptops">← Volver a equipos</a><section class="panel detail"><div><p class="eyebrow">${esc(x.service_tag)}</p><h2>${esc(x.marca)} ${esc(x.modelo)}</h2><span class="badge">${esc(x.estado)}</span><dl><dt>Serial</dt><dd>${esc(x.serial)}</dd><dt>Observaciones</dt><dd>${esc(x.observaciones||'Sin observaciones')}</dd></dl></div><div class="qr" data-qr-box="${x.id}"></div></section><section class="panel components-panel"><div class="panel-title"><div><p class="eyebrow">ESPECIFICACIONES TÉCNICAS</p><h2>Componentes</h2></div>${user.role==='admin'?'<button class="btn secondary" data-open="components">Editar componentes</button>':''}</div><div class="spec-grid">${Object.entries(c).filter(([,v])=>v).map(([k,v])=>`<article class="spec-item"><span>${esc(COMPONENT_LABELS[k]||k.replaceAll('_',' '))}</span><strong>${esc(v)}</strong></article>`).join('')||'<p class="empty">Sin especificaciones.</p>'}</div></section><section class="panel"><h2>Historial de préstamos</h2><div class="table-scroll"><table><thead><tr><th>Persona</th><th>Entrega</th><th>Devolución</th><th>Estado</th></tr></thead><tbody>${loans.map(l=>`<tr><td>${esc(byId(db.employees,l.employee_id)?.nombre)}</td><td>${l.fecha_entrega}</td><td>${l.fecha_retorno||l.fecha_devolucion||'—'}</td><td>${l.estado}</td></tr>`).join('')||empty(4,'Sin historial.')}</tbody></table></div></section>${modal('components',modalHead('Editar componentes','Organiza las especificaciones técnicas del equipo.')+`<form data-action="components" data-id="${x.id}"><div class="form-grid">${fields.map(f=>`<label>${esc(COMPONENT_LABELS[f])}${f==='notes'?`<textarea name="${f}">${esc(c[f])}</textarea>`:`<input name="${f}" value="${esc(c[f])}">`}</label>`).join('')}</div><div class="modal-actions"><button class="btn primary">Guardar</button></div></form>`)}`);}
  function employees(){return shell('Personas',`<section class="toolbar"><input class="search" data-table-search="employees-table" placeholder="Buscar por nombre, cédula o departamento"><button class="btn primary" data-open="newEmployee">+ Nueva persona</button></section><section class="panel"><div class="table-scroll"><table id="employees-table"><thead><tr><th data-sort>Nombre ↕</th><th>Cédula</th><th>Departamento</th><th>Correo</th><th>Acciones</th></tr></thead><tbody>${db.employees.map(x=>`<tr><td><a class="link" href="#/employees/${x.id}">${esc(x.nombre)}</a></td><td>${esc(x.cedula)}</td><td>${esc(x.departamento||'—')}</td><td>${esc(x.correo||'—')}</td><td class="row-actions"><a class="icon-btn" href="#/employees/${x.id}">↗</a><button class="icon-btn danger" data-delete="employees:${x.id}:${esc(x.nombre)}">×</button></td></tr>`).join('')||empty(5,'No hay personas registradas.')}</tbody></table></div><div class="pagination" data-pagination="employees-table"></div></section>${modal('newEmployee',modalHead('Registrar persona','Datos de contacto y departamento.')+`<form data-action="create-employee"><div class="form-grid"><label>Nombre completo<input name="nombre" required></label><label>Cédula<input name="cedula" required pattern="[0-9-]{9,15}"></label><label>Departamento<input name="departamento"></label><label>Correo<input type="email" name="correo"></label><label>Teléfono<input type="tel" name="telefono"></label></div><div class="modal-actions"><button class="btn primary">Guardar persona</button></div></form>`)}`);}
  function employeeDetail(id){const x=byId(db.employees,id);if(!x)return notFound();const loans=db.loans.filter(l=>l.employee_id===x.id);return shell('Perfil de persona',`<a class="back" href="#/employees">← Volver a personas</a><section class="panel detail"><div><p class="eyebrow">${esc(x.departamento||'SIN DEPARTAMENTO')}</p><h2>${esc(x.nombre)}</h2><dl><dt>Cédula</dt><dd>${esc(x.cedula)}</dd><dt>Correo</dt><dd>${esc(x.correo||'—')}</dd><dt>Teléfono</dt><dd>${esc(x.telefono||'—')}</dd></dl></div><div class="stat-circle"><strong>${loans.length}</strong><span>préstamos<br>registrados</span></div></section><section class="panel"><h2>Historial de préstamos</h2><div class="table-scroll"><table><thead><tr><th>Equipo</th><th>Entrega</th><th>Devolución</th><th>Estado</th></tr></thead><tbody>${loans.map(l=>`<tr><td>${esc(byId(db.laptops,l.laptop_id)?.service_tag)}</td><td>${l.fecha_entrega}</td><td>${l.fecha_retorno||l.fecha_devolucion||'—'}</td><td>${l.estado}</td></tr>`).join('')||empty(4,'Sin historial de préstamos.')}</tbody></table></div></section>`);}
  function accessories(){return shell('Accesorios',`<section class="toolbar"><input class="search" data-table-search="accessories-table" placeholder="Buscar accesorio"><button class="btn primary" data-open="newAccessory">+ Nuevo accesorio</button></section><section class="panel"><div class="table-scroll"><table id="accessories-table"><thead><tr><th data-sort>Nombre ↕</th><th data-sort>Tipo ↕</th><th>Acciones</th></tr></thead><tbody>${db.accessories.map(x=>`<tr><td>${esc(x.nombre)}</td><td>${esc(x.tipo)}</td><td><button class="icon-btn danger" data-delete="accessories:${x.id}:${esc(x.nombre)}">×</button></td></tr>`).join('')||empty(3,'No hay accesorios registrados.')}</tbody></table></div></section>${modal('newAccessory',modalHead('Registrar accesorio','Agrega un accesorio al inventario.')+`<form data-action="create-accessory"><div class="form-grid"><label>Nombre<input name="nombre" required></label><label>Tipo<input name="tipo" required></label></div><div class="modal-actions"><button class="btn primary">Guardar accesorio</button></div></form>`)}`);}
  function loans(){const admin=user.role==='admin',available=db.laptops.filter(x=>x.estado==='Disponible');return shell('Préstamos',`<section class="toolbar"><input class="search" data-table-search="loans-table" placeholder="Buscar persona o equipo">${admin?'<button class="btn primary" data-open="newLoan">+ Nuevo préstamo</button>':''}</section><section class="panel"><div class="table-scroll"><table id="loans-table"><thead><tr><th>Persona</th><th>Equipo</th><th>Entrega</th><th>Devolución</th><th>Estado</th><th>Firmas</th><th></th></tr></thead><tbody>${db.loans.slice().sort((a,b)=>b.id-a.id).map(x=>`<tr><td>${esc(byId(db.employees,x.employee_id)?.nombre)}</td><td>${esc(byId(db.laptops,x.laptop_id)?.service_tag)}</td><td>${x.fecha_entrega}</td><td>${x.fecha_retorno||x.fecha_devolucion||'—'}</td><td><span class="badge ${x.estado==='Activo'?'amber':'green'}">${x.estado}</span></td><td>${x.signatures?.length?x.signatures.map((s,i)=>`<button class="link signature-link" data-signature="${x.id}:${i}">${esc(s.type)}</button>`).join(' · '):'—'}</td><td>${admin&&x.estado==='Activo'?`<button class="btn secondary" data-open="return${x.id}">Devolver</button>`:''}</td></tr>`).join('')||empty(7,'No hay préstamos registrados.')}</tbody></table></div></section>${admin?modal('newLoan',modalHead('Registrar préstamo')+`<form data-action="create-loan"><div class="form-grid"><label>Persona<select name="employee_id" required>${options(db.employees,null)}</select></label><label>Laptop disponible<select name="laptop_id" required>${options(available,null,x=>`${x.service_tag} · ${x.marca}`)}</select></label><label>Fecha de entrega<input type="date" name="fecha_entrega" value="${today()}" required></label><label>Fecha prevista<input type="date" name="fecha_devolucion"></label><label>Accesorios<select name="accessory_ids" multiple>${options(db.accessories,null)}</select></label><label>Observaciones<textarea name="observaciones"></textarea></label></div><div class="signature-box"><label>Firma de entrega</label><canvas class="signature-canvas"></canvas><input type="hidden" name="signature_entrega"><button type="button" class="btn secondary clear-signature">Limpiar firma</button></div><div class="modal-actions"><button class="btn primary" ${available.length?'':'disabled'}>Registrar préstamo</button></div></form>`)+db.loans.filter(x=>x.estado==='Activo').map(x=>modal(`return${x.id}`,modalHead(`Devolución: ${byId(db.laptops,x.laptop_id)?.service_tag}`)+`<form data-action="return-loan" data-id="${x.id}"><div class="signature-box"><label>Firma de devolución</label><canvas class="signature-canvas"></canvas><input type="hidden" name="signature_devolucion"><button type="button" class="btn secondary clear-signature">Limpiar firma</button></div><div class="modal-actions"><button class="btn primary">Confirmar devolución</button></div></form>`)).join(''):''}`);}
  function incidents(){const priorities=['Baja','Media','Alta','Crítica'],statuses=['Abierta','En proceso','En espera','Cerrada'];const fields=(x={})=>`<div class="form-grid"><label>Equipo<select name="laptop_id" ${x.id?'disabled':''}>${options(db.laptops,x.laptop_id,y=>y.service_tag)}</select></label><label>Usuario relacionado<select name="employee_id"><option value="">Sin asignar</option>${options(db.employees,x.employee_id)}</select></label><label>Técnico<select name="technician_id"><option value="">Sin asignar</option>${options(db.technicians,x.technician_id,y=>y.name)}</select></label><label>Prioridad<select name="priority">${priorities.map(v=>`<option ${x.priority===v?'selected':''}>${v}</option>`)}</select></label><label>Categoría<input name="category" value="${esc(x.category)}" required></label><label>Estado<select name="status_value">${statuses.map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`)}</select></label><label>Descripción<textarea name="description" required>${esc(x.description)}</textarea></label><label>Solución aplicada<textarea name="solution">${esc(x.solution)}</textarea></label></div>`;return shell('Incidencias',`<section class="toolbar"><input class="search" data-table-search="incidents-table" placeholder="Buscar equipo, categoría o técnico"><button class="btn primary" data-open="newIncident">+ Nueva incidencia</button></section><section class="panel"><div class="table-scroll"><table id="incidents-table"><thead><tr><th>Equipo</th><th>Categoría</th><th>Prioridad</th><th>Estado</th><th>Técnico</th><th>Creada</th><th></th></tr></thead><tbody>${db.incidents.map(x=>`<tr><td>${esc(byId(db.laptops,x.laptop_id)?.service_tag)}</td><td>${esc(x.category)}</td><td><span class="badge ${['Alta','Crítica'].includes(x.priority)?'red':'amber'}">${x.priority}</span></td><td>${x.status}</td><td>${esc(byId(db.technicians,x.technician_id)?.name||'Sin asignar')}</td><td>${x.created_at}</td><td><button class="btn secondary" data-open="incident${x.id}">Gestionar</button></td></tr>`).join('')||empty(7,'No hay incidencias registradas.')}</tbody></table></div></section>${modal('newIncident',modalHead('Nueva incidencia')+`<form data-action="create-incident">${fields()}<div class="modal-actions"><button class="btn primary">Crear incidencia</button></div></form>`)}${db.incidents.map(x=>modal(`incident${x.id}`,modalHead(`Incidencia #${x.id}`)+`<form data-action="edit-incident" data-id="${x.id}">${fields(x)}<div class="modal-actions"><button class="btn primary">Guardar</button></div></form>`)).join('')}`);}
  function maintenance(){const statuses=['Recibido','En diagnóstico','En reparación','En espera de repuesto','Finalizado','Entregado'];const techStats=db.technicians.map(t=>{const list=db.maintenance.filter(x=>x.technician_id===t.id),done=list.filter(x=>['Finalizado','Entregado'].includes(x.status));return {t,total:list.length,pending:list.length-done.length,done:done.length,avg:list.length?(list.reduce((s,x)=>s+Number(x.hours_spent||0),0)/list.length).toFixed(1):'0.0'};});const edit=x=>`<div class="form-grid"><label>Técnico<select name="technician_id"><option value="">Sin asignar</option>${options(db.technicians.filter(t=>t.active),x.technician_id,t=>t.name)}</select></label><label>Estado<select name="status_value">${statuses.map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`)}</select></label><label>Solución<textarea name="solution">${esc(x.solution)}</textarea></label><label>Repuestos<textarea name="parts_used">${esc(x.parts_used)}</textarea></label><label>Observaciones<textarea name="notes">${esc(x.notes)}</textarea></label><label>Horas<input type="number" min="0" step=".1" name="hours_spent" value="${x.hours_spent||0}"></label><label>Costo<input type="number" min="0" step=".01" name="repair_cost" value="${x.repair_cost||0}"></label><label>Garantía días<input type="number" min="0" name="warranty_days" value="${x.warranty_days||0}"></label></div>`;return shell('Mantenimiento',`<section class="toolbar"><button class="btn secondary" data-open="newTech">Técnicos</button><button class="btn primary" data-open="newMaintenance">+ Mantenimiento</button></section><section class="panel"><div class="table-scroll"><table><thead><tr><th>Equipo</th><th>Técnico</th><th>Estado</th><th>Ingreso</th><th>Estimado</th><th>Horas</th><th>Costo</th><th></th></tr></thead><tbody>${db.maintenance.map(x=>`<tr><td>${esc(byId(db.laptops,x.laptop_id)?.service_tag)}</td><td>${esc(byId(db.technicians,x.technician_id)?.name||'Sin asignar')}</td><td><span class="badge amber">${x.status}</span></td><td>${x.received_at}</td><td>${x.estimated_delivery||'—'}</td><td>${x.hours_spent||0}</td><td>RD$ ${Number(x.repair_cost||0).toLocaleString()}</td><td><button class="btn secondary" data-open="maintenance${x.id}">Gestionar</button></td></tr>`).join('')||empty(8,'Sin mantenimientos.')}</tbody></table></div></section><section class="panel"><h2>Estadísticas por técnico</h2><div class="table-scroll"><table><thead><tr><th>Técnico</th><th>Realizados</th><th>Pendientes</th><th>Finalizados</th><th>Horas promedio</th></tr></thead><tbody>${techStats.map(x=>`<tr><td>${esc(x.t.name)}</td><td>${x.total}</td><td>${x.pending}</td><td>${x.done}</td><td>${x.avg}</td></tr>`).join('')}</tbody></table></div></section>${modal('newTech',modalHead('Nuevo técnico')+`<form data-action="create-tech"><div class="form-grid"><label>Nombre<input name="name" required></label><label>Especialidad<input name="specialty"></label><label>Correo<input name="email" type="email"></label><label>Teléfono<input name="phone" type="tel"></label></div><div class="modal-actions"><button class="btn primary">Guardar técnico</button></div></form>`)}${modal('newMaintenance',modalHead('Registrar mantenimiento')+`<form data-action="create-maintenance"><div class="form-grid"><label>Equipo<select name="laptop_id">${options(db.laptops,null,x=>x.service_tag)}</select></label><label>Incidencia<select name="incident_id"><option value="">Sin incidencia</option>${options(db.incidents,null,x=>`#${x.id} ${x.category}`)}</select></label><label>Técnico activo<select name="technician_id"><option value="">Sin asignar</option>${options(db.technicians.filter(x=>x.active),null,x=>x.name)}</select></label><label>Estado<select name="status_value">${statuses.map(v=>`<option>${v}</option>`)}</select></label><label>Prioridad<select name="priority"><option>Baja</option><option selected>Media</option><option>Alta</option><option>Crítica</option></select></label><label>Ingreso<input type="date" name="received_at" value="${today()}" required></label><label>Entrega estimada<input type="date" name="estimated_delivery"></label><label>Diagnóstico<textarea name="initial_diagnosis"></textarea></label><label>Observaciones<textarea name="notes"></textarea></label></div><div class="modal-actions"><button class="btn primary">Registrar</button></div></form>`)}${db.maintenance.map(x=>modal(`maintenance${x.id}`,modalHead(`Mantenimiento #${x.id}`)+`<form data-action="edit-maintenance" data-id="${x.id}">${edit(x)}<div class="modal-actions"><button class="btn primary">Actualizar</button></div></form>`)).join('')}`);}
  function users(){return shell('Usuarios y roles',`<section class="toolbar"><input class="search" data-table-search="users-table" placeholder="Buscar usuario o rol"><button class="btn primary" data-open="newUser">+ Nuevo usuario</button></section><section class="panel"><div class="table-scroll"><table id="users-table"><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Persona vinculada</th><th>Acciones</th></tr></thead><tbody>${db.users.map(x=>`<tr><td><strong>${esc(x.username)}</strong>${x.id===user.id?' <span class="badge green">Tú</span>':''}</td><td>${esc(x.email)}</td><td><span class="badge ${x.role==='admin'?'green':'amber'}">${x.role==='admin'?'Administrador':'Visitante'}</span></td><td>${esc(byId(db.employees,x.employee_id)?.nombre||'—')}</td><td class="row-actions"><button class="icon-btn" data-open="user${x.id}">✎</button>${x.id!==user.id?`<button class="icon-btn danger" data-delete="users:${x.id}:${esc(x.username)}">×</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="pagination" data-pagination="users-table"></div></section>${modal('newUser',modalHead('Crear usuario','Asigna acceso y rol a una persona.')+`<form data-action="create-user"><div class="form-grid"><label>Nombre<input name="username" minlength="3" required></label><label>Correo<input name="email" type="email" required></label><label>Contraseña<input type="password" name="password" minlength="8" required></label><label>Rol<select name="role"><option value="visitor">Visitante</option><option value="admin">Administrador</option></select></label><label>Persona vinculada<select name="employee_id"><option value="">Sin vincular</option>${options(db.employees,null)}</select></label></div><div class="modal-actions"><button class="btn primary">Crear usuario</button></div></form>`)}${db.users.map(x=>modal(`user${x.id}`,modalHead(`Editar ${x.username}`,'Deja la contraseña vacía para conservarla.')+`<form data-action="edit-user" data-id="${x.id}"><div class="form-grid"><label>Nombre<input name="username" value="${esc(x.username)}" minlength="3" required></label><label>Correo<input name="email" type="email" value="${esc(x.email)}" required></label><label>Rol<select name="role"><option value="admin" ${x.role==='admin'?'selected':''}>Administrador</option><option value="visitor" ${x.role==='visitor'?'selected':''}>Visitante</option></select></label><label>Nueva contraseña<input type="password" name="password" minlength="8"></label><label>Persona vinculada<select name="employee_id"><option value="">Sin vincular</option>${options(db.employees,x.employee_id)}</select></label></div><div class="modal-actions"><button class="btn primary">Guardar cambios</button></div></form>`)).join('')}`);}
  function auditView(){return shell('Auditoría',`<section class="toolbar"><input class="search" data-table-search="audit-table" placeholder="Buscar actividad"><button class="btn secondary" data-reset>Restablecer demo</button></section><section class="panel"><div class="table-scroll"><table id="audit-table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${db.audit.map(x=>`<tr><td>${new Date(x.date).toLocaleString('es-DO')}</td><td>${esc(x.user)}</td><td>${esc(x.action)}</td><td>${esc(x.detail)}</td></tr>`).join('')||empty(4,'Sin actividad registrada.')}</tbody></table></div><div class="pagination" data-pagination="audit-table"></div></section>`);}
  function about(){return shell('Acerca del sistema',`<section class="about-hero panel"><div class="about-logo">◆</div><div><p class="eyebrow">IT ASSET MANAGEMENT</p><h2>Sistema de Gestión de Activos Tecnológicos</h2><p>Una plataforma centralizada para administrar el ciclo de vida de tus equipos tecnológicos.</p></div><span class="about-status"><i></i> Demo offline</span></section><section class="about-grid"><article class="panel about-section"><div class="about-section-title"><span>◈</span><div><p class="eyebrow">PLATAFORMA</p><h2>Información del sistema</h2></div></div><dl class="about-info"><div><dt>Versión</dt><dd>3.0 Demo</dd></div><div><dt>Persistencia</dt><dd>LocalStorage</dd></div><div><dt>Servidor</dt><dd>No requerido</dd></div><div><dt>Compatibilidad</dt><dd>GitHub Pages / Offline</dd></div></dl></article><article class="panel about-section developer-card"><div class="about-section-title"><span>◉</span><div><p class="eyebrow">DESARROLLO</p><h2>Joel Domínguez</h2></div></div><p class="developer-role">Desarrollador Full Stack</p><p class="developer-copy">Especializado en soluciones tecnológicas empresariales, automatización y gestión de activos IT.</p><div class="skill-badges"><span>IT Support</span><span>IT Asset Management</span><span>JavaScript</span><span>LocalStorage</span><span>GitHub Pages</span></div></article></section>`);}
  function notFound(){return shell('Página no encontrada','<section class="panel"><h2>La vista solicitada no existe.</h2><a class="btn primary" href="#/dashboard">Volver al resumen</a></section>');}
  function protectedView(parts){if(user.role!=='admin'&&!['dashboard','loans','about'].includes(parts[0]))return dashboard();const views={dashboard,laptops,employees,accessories,loans,incidents,maintenance,users,audit:auditView,about};if(parts[0]==='laptops'&&parts[1])return laptopDetail(parts[1]);if(parts[0]==='employees'&&parts[1])return employeeDetail(parts[1]);return (views[parts[0]]||notFound)();}
  function render(){load();if(!user){login();showDemoNotice();return;}document.body.className=localStorage.getItem('theme')==='dark'?'dark':'';app.innerHTML=protectedView(route());bind();showDemoNotice();requestAnimationFrame(()=>document.querySelectorAll('.panel,.metrics article').forEach(x=>x.classList.add('ready')));}
  function formObject(form){return Object.fromEntries(new FormData(form).entries());}
  function requireUnique(list,key,val,current=0,message='El registro ya existe.'){if(list.some(x=>x.id!==Number(current)&&String(x[key]).toLowerCase()===String(val).toLowerCase()))throw new Error(message);}
  function handleAction(form){const a=form.dataset.action,d=formObject(form),id=Number(form.dataset.id);return perform('Guardando cambios…',()=>{
    if(a==='create-laptop'){requireUnique(db.laptops,'service_tag',d.service_tag,0,'Ese Service Tag ya está registrado.');db.laptops.push({id:nextId(db.laptops),...d,components:form.dataset.aiModel?clone(AI_CATALOG[form.dataset.aiModel].components):{}});audit(form.dataset.aiModel?'Equipo creado con IA demo':'Equipo creado',d.service_tag);aiSelection=null;}
    if(a==='edit-laptop'){requireUnique(db.laptops,'service_tag',d.service_tag,id,'Ese Service Tag ya está registrado.');Object.assign(byId(db.laptops,id),d);audit('Equipo actualizado',d.service_tag);}
    if(a==='components'){byId(db.laptops,id).components=d;audit('Componentes actualizados',byId(db.laptops,id).service_tag);}
    if(a==='create-employee'){requireUnique(db.employees,'cedula',d.cedula,0,'La cédula ya está registrada.');db.employees.push({id:nextId(db.employees),...d});audit('Persona creada',d.nombre);}
    if(a==='create-accessory'){db.accessories.push({id:nextId(db.accessories),...d});audit('Accesorio creado',d.nombre);}
    if(a==='create-loan'){const laptop=byId(db.laptops,d.laptop_id);if(!laptop||laptop.estado!=='Disponible')throw new Error('El equipo ya no está disponible.');if(!d.signature_entrega)throw new Error('Dibuja la firma de entrega antes de registrar el préstamo.');const selected=[...form.elements.accessory_ids.selectedOptions].map(x=>Number(x.value));db.loans.push({id:nextId(db.loans),employee_id:Number(d.employee_id),laptop_id:Number(d.laptop_id),fecha_entrega:d.fecha_entrega,fecha_devolucion:d.fecha_devolucion,estado:'Activo',accessory_ids:selected,observaciones:d.observaciones,signatures:[{type:'Entrega',data:d.signature_entrega,captured_at:new Date().toISOString(),demo:false}]});laptop.estado='Prestado';audit('Préstamo creado y firma capturada',laptop.service_tag);}
    if(a==='return-loan'){if(!d.signature_devolucion)throw new Error('Dibuja la firma de devolución antes de finalizar el préstamo.');const loan=byId(db.loans,id);loan.estado='Devuelto';loan.fecha_retorno=today();loan.signatures.push({type:'Devolución',data:d.signature_devolucion,captured_at:new Date().toISOString(),demo:false});byId(db.laptops,loan.laptop_id).estado='Disponible';audit('Préstamo devuelto y firma capturada',byId(db.laptops,loan.laptop_id).service_tag);}
    if(a==='create-incident'){db.incidents.push({id:nextId(db.incidents),laptop_id:Number(d.laptop_id),employee_id:Number(d.employee_id)||null,technician_id:Number(d.technician_id)||null,priority:d.priority,category:d.category,status:d.status_value,description:d.description,solution:d.solution,created_at:today()});audit('Incidencia creada',d.category);}
    if(a==='edit-incident'){Object.assign(byId(db.incidents,id),{employee_id:Number(d.employee_id)||null,technician_id:Number(d.technician_id)||null,priority:d.priority,category:d.category,status:d.status_value,description:d.description,solution:d.solution});audit('Incidencia actualizada',`#${id}`);}
    if(a==='create-tech'){db.technicians.push({id:nextId(db.technicians),...d,active:true});audit('Técnico creado',d.name);}
    if(a==='create-maintenance'){const laptop=byId(db.laptops,d.laptop_id);db.maintenance.push({id:nextId(db.maintenance),laptop_id:Number(d.laptop_id),incident_id:Number(d.incident_id)||null,technician_id:Number(d.technician_id)||null,status:d.status_value,priority:d.priority,received_at:d.received_at,estimated_delivery:d.estimated_delivery,initial_diagnosis:d.initial_diagnosis,notes:d.notes,hours_spent:0,repair_cost:0,warranty_days:0});laptop.estado='Mantenimiento';audit('Mantenimiento creado',laptop.service_tag);}
    if(a==='edit-maintenance'){const item=byId(db.maintenance,id);Object.assign(item,{technician_id:Number(d.technician_id)||null,status:d.status_value,solution:d.solution,parts_used:d.parts_used,notes:d.notes,hours_spent:Number(d.hours_spent),repair_cost:Number(d.repair_cost),warranty_days:Number(d.warranty_days)});if(['Finalizado','Entregado'].includes(item.status))byId(db.laptops,item.laptop_id).estado='Disponible';audit('Mantenimiento actualizado',`#${id}`);}
    if(a==='create-user'){requireUnique(db.users,'email',d.email,0,'Ese correo ya tiene una cuenta.');db.users.push({id:nextId(db.users),username:d.username,email:d.email,password:d.password,role:d.role,employee_id:Number(d.employee_id)||null});audit('Usuario creado',d.email);}
    if(a==='edit-user'){requireUnique(db.users,'email',d.email,id,'Ese correo ya tiene una cuenta.');const target=byId(db.users,id);Object.assign(target,{username:d.username,email:d.email,role:d.role,employee_id:Number(d.employee_id)||null});if(d.password)target.password=d.password;audit('Usuario actualizado',d.email);}
  });}
  function setupTable(table){const rows=[...table.tBodies[0].rows].filter(r=>!r.querySelector('.empty'));let page=1;const pager=document.querySelector(`[data-pagination="${table.id}"]`);const draw=()=>{const visible=rows.filter(r=>r.dataset.match!=='false'&&r.dataset.filter!=='false'),pages=Math.max(1,Math.ceil(visible.length/PAGE_SIZE));page=Math.min(page,pages);rows.forEach(r=>r.style.display='none');visible.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE).forEach(r=>r.style.display='');if(pager){pager.innerHTML='';for(let n=1;n<=pages;n++){const b=document.createElement('button');b.textContent=n;b.className=n===page?'active':'';b.onclick=()=>{page=n;draw();};pager.append(b);}}};document.querySelectorAll(`[data-table-search="${table.id}"]`).forEach(i=>i.oninput=()=>{const q=i.value.toLowerCase();rows.forEach(r=>r.dataset.match=String(r.innerText).toLowerCase().includes(q));page=1;draw();});document.querySelectorAll(`[data-table-filter="${table.id}"]`).forEach(i=>i.onchange=()=>{const q=i.value.toLowerCase(),col=Number(i.dataset.column);rows.forEach(r=>r.dataset.filter=!q||r.cells[col]?.textContent.trim().toLowerCase()===q);page=1;draw();});table.querySelectorAll('[data-sort]').forEach((h,col)=>h.onclick=()=>{const asc=h.dataset.direction!=='asc';h.dataset.direction=asc?'asc':'desc';rows.sort((a,b)=>a.cells[col].textContent.localeCompare(b.cells[col].textContent,'es',{numeric:true})*(asc?1:-1));rows.forEach(r=>table.tBodies[0].append(r));draw();});draw();}
  function setupSignature(canvas){if(canvas.dataset.ready)return;canvas.dataset.ready='true';const hidden=canvas.parentElement.querySelector('input[type=hidden]'),ctx=canvas.getContext('2d');let drawing=false,last;const resize=()=>{const rect=canvas.getBoundingClientRect();canvas.width=Math.max(rect.width,300);canvas.height=Math.max(rect.height,120);ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#172033';};const finish=()=>{if(!drawing)return;drawing=false;hidden.value=canvas.toDataURL('image/png');canvas.classList.toggle('has-signature',Boolean(hidden.value));};setTimeout(resize,0);canvas.onpointerdown=e=>{drawing=true;last={x:e.offsetX,y:e.offsetY};canvas.setPointerCapture?.(e.pointerId);};canvas.onpointermove=e=>{if(!drawing)return;ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(e.offsetX,e.offsetY);ctx.stroke();last={x:e.offsetX,y:e.offsetY};};canvas.onpointerup=finish;canvas.onpointercancel=finish;canvas.parentElement.querySelector('.clear-signature').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);hidden.value='';canvas.classList.remove('has-signature');};}
  function assetUrl(x){const url=new URL(location.href);url.hash=`#/laptops/${x.id}`;return url.href;}
  function qrData(x){const qr=qrcode(0,'M');qr.addData(assetUrl(x));qr.make();return qr.createDataURL(8,4);}
  function openQr(x){const w=window.open('','_blank','width=520,height=680');if(!w){toast('El navegador bloqueó la ventana.','error');return;}w.document.write(`<title>QR ${esc(x.service_tag)}</title><style>body{font-family:Arial;text-align:center;padding:35px;color:#172033}img{width:340px;image-rendering:pixelated}small{display:block;margin:8px}.url{font-size:10px;overflow-wrap:anywhere;color:#667085}@media print{button{display:none}}</style><h2>${esc(x.marca)} ${esc(x.modelo)}</h2><img src="${qrData(x)}" alt="Código QR"><h3>${esc(x.service_tag)}</h3><small>Serial: ${esc(x.serial)}</small><p class="url">${esc(assetUrl(x))}</p><button onclick="print()">Imprimir QR</button>`);w.document.close();}
  function openSignature(loan,index){const signature=loan.signatures[index],employee=byId(db.employees,loan.employee_id),laptop=byId(db.laptops,loan.laptop_id),isDemo=!signature.data||signature.demo,data=signature.data||demoSignature(employee?.nombre,signature.type),date=signature.captured_at?new Date(signature.captured_at).toLocaleString('es-DO'):(signature.type==='Entrega'?loan.fecha_entrega:loan.fecha_retorno||loan.fecha_devolucion);const viewer=document.createElement('div');viewer.className='modal active signature-viewer';viewer.innerHTML=`<div class="modal-content"><div class="modal-header"><div><p class="eyebrow">COMPROBANTE DE ${esc(signature.type).toUpperCase()}</p><h2>Firma del préstamo #${loan.id}</h2></div><button class="close" type="button">×</button></div>${isDemo?'<div class="signature-demo-label">Firma predefinida para fines de demostración</div>':''}<div class="signature-document"><img src="${data}" alt="Firma de ${esc(employee?.nombre)}"><dl><div><dt>Firmante</dt><dd>${esc(employee?.nombre)}</dd></div><div><dt>Equipo</dt><dd>${esc(laptop?.service_tag)}</dd></div><div><dt>Tipo</dt><dd>${esc(signature.type)}</dd></div><div><dt>Fecha registrada</dt><dd>${esc(date)}</dd></div></dl></div><div class="modal-actions"><button class="btn primary" type="button" data-signature-close>Cerrar comprobante</button></div></div>`;document.body.append(viewer);document.body.classList.add('modal-open');const close=()=>{viewer.remove();document.body.classList.remove('modal-open');};viewer.querySelector('.close').onclick=close;viewer.querySelector('[data-signature-close]').onclick=close;viewer.onclick=e=>{if(e.target===viewer)close();};}
  function bind(){
    document.querySelectorAll('.login-mark,.about-logo').forEach(mark=>{mark.replaceChildren(Object.assign(document.createElement('img'),{src:'app/static/img/favicon.svg',alt:'IT Asset Manager'}));});
    document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const m=document.getElementById(b.dataset.open);m?.classList.add('active');document.body.classList.add('modal-open');m?.querySelectorAll('canvas').forEach(setupSignature);});
    document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{b.closest('.modal')?.classList.remove('active');document.body.classList.remove('modal-open');});
    document.querySelectorAll('.modal').forEach(m=>m.onclick=e=>{if(e.target===m){m.classList.remove('active');document.body.classList.remove('modal-open');}});
    document.querySelector('.menu-toggle')?.addEventListener('click',()=>document.getElementById('sidebar')?.classList.add('open'));document.querySelectorAll('[data-sidebar-close]').forEach(x=>x.onclick=()=>document.getElementById('sidebar')?.classList.remove('open'));
    document.querySelector('.theme-toggle')?.addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('theme',document.body.classList.contains('dark')?'dark':'light');});
    document.querySelector('[data-logout]')?.addEventListener('click',()=>{localStorage.removeItem(SESSION_KEY);user=null;render();});
    document.querySelectorAll('form[data-action]').forEach(form=>form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;if(form.dataset.action==='login'){const found=db.users.find(x=>x.email.toLowerCase()===value(form,'email').toLowerCase()&&x.password===value(form,'password'));loader('Verificando credenciales…');delay().then(()=>{stopLoader();if(!found){document.getElementById('login-error').innerHTML='<div class="alert alert-danger">Correo o contraseña incorrectos.</div>';return;}localStorage.setItem(SESSION_KEY,JSON.stringify({userId:found.id}));if(route()[0]==='dashboard')navigate('dashboard');else render();});return;}handleAction(form);});
    document.querySelectorAll('table[id]').forEach(setupTable);
    document.querySelectorAll('[data-edit-laptop]').forEach(b=>b.onclick=()=>document.getElementById(`editLaptop${b.dataset.editLaptop}`)?.classList.add('active'));
    document.querySelector('[data-ai-search]')?.addEventListener('click',async event=>{const key=document.getElementById('aiDemoModel').value,item=AI_CATALOG[key],loading=document.getElementById('aiDemoLoading'),preview=document.getElementById('aiDemoPreview'),apply=document.getElementById('aiDemoApply');event.currentTarget.disabled=true;loading.hidden=false;preview.hidden=true;apply.hidden=true;await delay();aiSelection=key;preview.innerHTML=`<div class="ai-preview-row"><span>Marca</span><strong>${esc(item.marca)}</strong></div><div class="ai-preview-row"><span>Modelo</span><strong>${esc(item.modelo)}</strong></div><div class="ai-preview-row"><span>Procesador</span><strong>${esc(item.components.processor)}</strong></div><div class="ai-preview-row"><span>Memoria RAM</span><strong>${esc(item.components.ram)}</strong></div><div class="ai-preview-row"><span>Almacenamiento</span><strong>${esc(item.components.primary_disk)}</strong></div><div class="ai-preview-row"><span>Pantalla</span><strong>${esc(item.components.display)} · ${esc(item.components.resolution)}</strong></div><p class="ai-warning">Propuesta generada con datos locales predefinidos para esta demostración.</p>`;loading.hidden=true;preview.hidden=false;apply.hidden=false;event.currentTarget.disabled=false;});
    document.querySelector('[data-ai-apply]')?.addEventListener('click',()=>{if(!aiSelection)return;const item=AI_CATALOG[aiSelection],form=document.querySelector('form[data-action="create-laptop"]');let tag=item.service_tag,index=2;while(db.laptops.some(x=>x.service_tag.toLowerCase()===tag.toLowerCase()))tag=`${item.service_tag}-${index++}`;form.elements.service_tag.value=tag;form.elements.marca.value=item.marca;form.elements.modelo.value=item.modelo;form.elements.serial.value=item.serial.replace('DEMO',String(Date.now()).slice(-4));form.elements.estado.value='Disponible';form.elements.observaciones.value='Equipo generado mediante el asistente de IA simulada con datos predefinidos.';form.dataset.aiModel=aiSelection;document.getElementById('aiLaptop').classList.remove('active');document.getElementById('newLaptop').classList.add('active');toast('Propuesta local aplicada. Revisa los datos antes de guardar.');});
    document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const [collection,id,label]=b.dataset.delete.split(':');if(!confirm(`¿Eliminar "${label}"? Esta acción no se puede deshacer.`))return;perform('Eliminando…',()=>{if(collection==='laptops'&&db.loans.some(x=>x.laptop_id===Number(id)&&x.estado==='Activo'))throw new Error('No se puede eliminar un equipo con préstamo activo.');db[collection]=db[collection].filter(x=>x.id!==Number(id));audit('Registro eliminado',label);});});
    document.querySelectorAll('[data-qr]').forEach(b=>b.onclick=()=>openQr(byId(db.laptops,b.dataset.qr)));
    document.querySelectorAll('[data-qr-box]').forEach(box=>{const x=byId(db.laptops,box.dataset.qrBox);box.innerHTML=`<img src="${qrData(x)}" alt="Código QR escaneable de ${esc(x.service_tag)}"><small>Al escanear abre la ficha de este equipo.</small><button class="btn secondary">Abrir código QR</button>`;box.querySelector('button').onclick=()=>openQr(x);});
    document.querySelectorAll('.signature-box').forEach(box=>{const hint=document.createElement('p');hint.className='signature-help';hint.textContent='Dibuja dentro del recuadro. La firma se guardará con el préstamo y podrás verla desde la tabla.';box.querySelector('label')?.after(hint);});
    document.querySelectorAll('.signature-link').forEach(b=>{b.classList.add('signature-pill');b.type='button';b.insertAdjacentText('afterbegin','✎ ');b.title='Ver comprobante de firma';b.onclick=()=>{const [loanId,index]=b.dataset.signature.split(':');openSignature(byId(db.loans,loanId),Number(index));};});
    document.querySelector('[data-reset]')?.addEventListener('click',()=>{if(confirm('¿Restablecer todos los datos de demostración?')){localStorage.removeItem(DB_KEY);render();toast('Datos restablecidos');}});
    const active=route()[0];document.querySelector(`[data-route="${active}"]`)?.classList.add('active');
  }
  window.addEventListener('hashchange',render);window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.modal.active').forEach(x=>x.classList.remove('active'));document.body.classList.remove('modal-open');}});load();render();
}());
